const res = $input.first().json;
const statusCode = res.statusCode || (res.body ? 200 : 500);

// 1. Fehlerüberprüfung: Hat eLabFTW einen Fehlercode zurückgegeben?
if (statusCode >= 400 || (res.body && res.body.error) || (res.body && res.body.message && !Array.isArray(res.body))) {
  const errMsg = res.body?.message || res.body?.error || `HTTP Status ${statusCode}`;
  return {
    json: {
      status: 'error',
      statusCode: statusCode,
      message: `eLabFTW Serverfehler (${statusCode}): ${errMsg}. Bitte eLabFTW API-Key & Host prüfen!`
    }
  };
}

// 2. Antwortliste extrahieren
let rawList = [];
if (res.body && Array.isArray(res.body)) {
  rawList = res.body;
} else if (Array.isArray(res)) {
  rawList = res;
} else if (res.body && typeof res.body === 'object' && Array.isArray(res.body.templates)) {
  rawList = res.body.templates;
}

// 3. Vorlagen sauber formatieren
const formattedList = rawList.map(t => {
  let meta = t.metadata;
  if (typeof meta === 'string') {
    try { meta = JSON.parse(meta); } catch (e) { meta = {}; }
  }
  return {
    id: t.id,
    title: t.title || t.name || `Vorlage #${t.id}`,
    category: t.category || 'eLabFTW',
    description: t.description || '',
    metadata: meta || {}
  };
});

// KEIN Demodaten-Fallback mehr: Klare, ehrliche Rückmeldung!
return {
  json: {
    status: 'success',
    statusCode: statusCode,
    count: formattedList.length,
    templates: formattedList,
    message: formattedList.length === 0
      ? '0 Vorlagen in eLabFTW gefunden. Bitte prüfe, ob dein Account bzw. Team unter „Experimente > Vorlagen“ Vorlagen besitzt.'
      : `Erfolgreich ${formattedList.length} Vorlagen aus eLabFTW geladen.`
  }
};
